param ( [string]$SubscriptionUrl = 'https://whua-bp.8dy.xx.kg/sub/normal/wh898?app=xray#%F0%9F%92%A6%20BPB%20Normal', [string]$Target = 'v2ray' ) $ErrorActionPreference = 'Stop' Write-Host '========================================' -ForegroundColor Cyan Write-Host '快速诊断: 订阅源转换测试' -ForegroundColor Cyan Write-Host '========================================' -ForegroundColor Cyan Write-Host '' Write-Host '[1] 测试原始订阅源 (target='$Target')...' -ForegroundColor Yellow try { $response = Invoke-WebRequest -Uri $SubscriptionUrl -TimeoutSec 30 -UseBasicParsing $statusCode = $response.StatusCode $content = $response.Content Write-Host " HTTP 状态: $statusCode" -ForegroundColor Green Write-Host " 内容长度: $($content.Length) 字符" -ForegroundColor Green } catch { Write-Host " 访问失败: $_" -ForegroundColor Red exit 1 } Write-Host '' Write-Host '[2] 分析输出格式...' -ForegroundColor Yellow $trimmed = $content.Trim() $isBase64 = $false $decoded = '' try { $bytes = [Convert]::FromBase64String($trimmed) $decoded = [Text.Encoding]::UTF8.GetString($bytes) $isBase64 = $true Write-Host ' 合法 Base64: 是' -ForegroundColor Green Write-Host " 解码长度: $($decoded.Length) 字符" -ForegroundColor Green } catch { Write-Host ' 合法 Base64: 否' -ForegroundColor Red $padded = $trimmed + ('=' * (4 - $trimmed.Length % 4)) if ($padded.Length -ne $trimmed.Length) { try { $bytes = [Convert]::FromBase64String($padded) $decoded = [Text.Encoding]::UTF8.GetString($bytes) $isBase64 = $true Write-Host ' 补全 padding 后有效' -ForegroundColor Yellow Write-Host " 解码长度: $($decoded.Length) 字符" -ForegroundColor Green } catch { Write-Host ' 补全 padding 仍无效' -ForegroundColor Red } } } Write-Host '' Write-Host '[3] 统计协议节点...' -ForegroundColor Yellow $protocols = @{ 'vmess://' = 0; 'vless://' = 0; 'trojan://' = 0; 'ss://' = 0; 'ssr://' = 0; 'hysteria2://' = 0; 'tuic://' = 0 } if ($decoded) { foreach ($proto in $protocols.Keys) { $protocols[$proto] = ([regex]::Matches($decoded, [regex]::Escape($proto))).Count } $total = ($protocols.Values | Measure-Object -Sum).Sum Write-Host ' 节点统计:' -ForegroundColor Cyan foreach ($proto in $protocols.Keys) { if ($protocols[$proto] -gt 0) { Write-Host " $proto : $($protocols[$proto]) 个" -ForegroundColor Green } } Write-Host " 总节点数: $total" -ForegroundColor Cyan } else { Write-Host ' 无解码内容 (Base64 无效)' -ForegroundColor Red } Write-Host '' Write-Host '[4] 诊断结论:' -ForegroundColor Yellow $allGood = $isBase64 -and ($protocols.Values | Where-Object { $_ -gt 0 }) if ($allGood) { Write-Host ' ✓ 订阅源转换正常，无需修复' -ForegroundColor Green exit 0 } else { Write-Host ' ✗ 发现问题:' -ForegroundColor Red if (-not $isBase64) { Write-Host ' - 输出不是合法 Base64' } if ($total -eq 0) { Write-Host ' - 无有效协议节点' } Write-Host ' 需要进入自动修复流程' -ForegroundColor Yellow exit 1 }